mapper.update:
UPDATE media_scan_task SET status='INTERRUPTED', active_source=NULL,
    error='服务已重启，扫描中断；请手动重新扫描', finished_at=#{now}
    WHERE active_source IS NOT NULL

mapper.delete:
DELETE FROM media_scan_task WHERE id IN (
    SELECT id FROM (SELECT DISTINCT old.id FROM media_scan_task old
    WHERE old.active_source IS NULL AND old.finished_at < #{before}
    AND EXISTS (SELECT 1 FROM media_scan_task newer WHERE newer.source_id=old.source_id
      AND (newer.created_at > old.created_at OR (newer.created_at=old.created_at AND newer.id > old.id)))) expired
    )
